INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',254,'{"_type":"chat:Message","id":"-5124234082:1927","threadId":"telegram:-5124234082","text":"J’ai fait un batch de granola ce matin avec 600g de flocons d’avoine.\nOn a fait la salade de pois chiches que tu as proposé ce midi.\nJ’ai acheté du liquide pour lave vaisselle, des olives noires dénoyautées, de l’origan, de la confiture de fraises pour le ptit dej des enfants. Garde tout ça en memoire pour une prochaine commande continente. \nCe soir on dine à la maison normalement. De mardi à samedi midi Lola n’est pas là, je serai seul avec les enfants. Jeudi c’est férié ils n’auront pas école. Mercredi soir je sortirai.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai fait un batch de granola ce matin avec 600g de flocons d’avoine.\nOn a fait la salade de pois chiches que tu as proposé ce midi.\nJ’ai acheté du liquide pour lave vaisselle, des olives noires dénoyautées, de l’origan, de la confiture de fraises pour le ptit dej des enfants. Garde tout ça en memoire pour une prochaine commande continente.\nCe soir on dine à la maison normalement. De mardi à samedi midi Lola n’est pas là, je serai seul avec les enfants. Jeudi c’est férié ils n’auront pas école. Mercredi soir je sortirai.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":184,"offset":527}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":184,"offset":527}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":184,"offset":527}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-31T13:15:59.000Z","edited":false},"attachments":[],"isMention":false}',1780838157829);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',255,'{"_type":"chat:Message","id":"-5124234082:1932","threadId":"telegram:-5124234082","text":"Hi Pepa, at lunch I was at the office. I didn''t eat the Bolognese. It''s still in the congelateur.\n\nFor dinner we would like to do some wraps with Panadoche. Can you give us a recipe? Also for the kids they love it.\n\nI didn''t do the batch cooking of Frango et Filochier. The vegetable basket will arrive probably on Thursday but I''m not sure because it''s a public holiday so I will confirm that later. On Wednesday I will be having dinner out","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hi Pepa, at lunch I was at the office. I didn''t eat the Bolognese. It''s still in the congelateur.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":98,"offset":97}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":98,"offset":97}}},{"type":"paragraph","children":[{"type":"text","value":"For dinner we would like to do some wraps with Panadoche. Can you give us a recipe? Also for the kids they love it.","position":{"start":{"line":3,"column":1,"offset":99},"end":{"line":3,"column":116,"offset":214}}}],"position":{"start":{"line":3,"column":1,"offset":99},"end":{"line":3,"column":116,"offset":214}}},{"type":"paragraph","children":[{"type":"text","value":"I didn''t do the batch cooking of Frango et Filochier. The vegetable basket will arrive probably on Thursday but I''m not sure because it''s a public holiday so I will confirm that later. On Wednesday I will be having dinner out","position":{"start":{"line":5,"column":1,"offset":216},"end":{"line":5,"column":226,"offset":441}}}],"position":{"start":{"line":5,"column":1,"offset":216},"end":{"line":5,"column":226,"offset":441}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":5,"column":226,"offset":441}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-01T16:33:07.000Z","edited":false},"attachments":[],"isMention":false}',1780936386360);
